INSERT INTO actions (action_score, category, guide_text, source) VALUES
    (2, '보습 및 제품 레이어링', '샤워 직후 3분 이내 보습제를 바르세요. 수분을 공급하는 크림을 먼저 바른 뒤 수분 증발을 막는 오일을 덧발라 수분 골든타임을 지키세요.', 'American Academy of Dermatology / 맘스홀릭 베이비'),
    (2, '보습 및 제품 레이어링', '피부가 건조할 때마다 하루 2~3회 이상 얇게 자주 덧바르세요. 외출 시에는 소형 오일 미스트나 튜브형 크림을 휴대하여 즉시 보습하세요.', '대한피부과의사회 / 파우더룸'),
    (2, '보습 및 제품 레이어링', '보습 크림을 손바닥에 덜어 5초간 비벼 온도를 높인 뒤 피부에 대어주세요. 손이 건조하면 보습제가 손으로 먼저 흡수되므로 마사지 전 손부터 촉촉하게 만드세요.', '한국피부미용학회 / 한국피부미용사회'),
    (3, '보습 및 제품 레이어링', '건조함이 심한 날에는 튼살 크림을 바른 뒤 랩을 5분간 올려두세요. 수분 증발을 막는 거즈 팩 원리를 활용해 진피층까지 수분을 전달하세요.', '국내 에스테틱 전문숍 노하우'),
    (1, '보습 및 제품 레이어링', '여름철에는 젤 타입 보습제나 가벼운 로션을 여러 번 덧바르세요. 환절기에는 세라마이드나 판테놀 성분의 보습제를 선택하세요.', 'American Academy of Dermatology / Korean Journal of Dermatology'),
    (1, '보습 및 제품 레이어링', '자주 다니는 동선마다 튼살 크림을 비치해 생각날 때마다 발라주세요.', '맘스홀릭 베이비'),
    (0, '보습 및 제품 레이어링', '복부가 본격적으로 부풀어 오르기 전인 임신 12주 차부터 피부 유연성을 pre-care 형태로 미리 확보해 진피층 파열을 사전 예방하세요.', 'American College of Obstetricians and Gynecologists / 대한산부인과학회'),
    (2, '보습 및 제품 레이어링', '히알루론산과 고농축 스쿠알란이 함유된 세럼을 크림 전 단계에 레이어링하여 피부 표피 아래 유·수분 장벽을 선제적으로 구축하세요.', 'Journal of Cosmetic Dermatology'),
    (3, '보습 및 제품 레이어링', '세라마이드, 콜레스테롤, 지방산이 3:1:1 피부 지질 유사 비율로 배합된 고보습 장벽 크림을 선택하여 손상된 피부 장벽을 복구하세요.', 'British Journal of Dermatology'),
    (2, '보습 및 제품 레이어링', '오일 단독 사용보다는 정제수나 세럼을 피부에 먼저 흡수시킨 후 오일 밀폐막을 형성해야 피부 표면의 수분 증발률(TEWL)을 낮출 수 있습니다.', 'International Journal of Cosmetic Science'),
    (0, '시기별·부위별 마사지 테크닉', '배가 본격적으로 부르기 전인 임신 초기부터 매일 꾸준히 마사지하세요. 부신 피질 호르몬으로 인한 콜라겐 파괴에 대비해 보습을 시작하세요.', 'Dermatologic Surgery / 우리여성병원'),
    (2, '시기별·부위별 마사지 테크닉', '임신 중기에는 매일 거울로 살이 트는 조짐을 확인하고, 10~20분간 배꼽을 중심으로 원을 그리며 마사지하세요.', '삼성서울병원 산부인과 / 우리여성병원'),
    (3, '시기별·부위별 마사지 테크닉', '임신 후기(36주 이후) 복부 마사지는 5분 이내로 줄이고 아주 부드럽게 문지르세요. 과도한 자극은 자궁 수축을 유발할 수 있습니다.', '서울아산병원 산부인과 Q&A'),
    (1, '시기별·부위별 마사지 테크닉', '아랫배, 엉덩이 아래, 허벅지 안쪽 등 눈에 잘 안 보이는 부위까지 거울로 체크하며 관리하세요.', '삼성서울병원 산부인과'),
    (2, '시기별·부위별 마사지 테크닉', '엉덩이와 옆구리는 밑에서 위쪽으로 쓰다듬어 올리며 보습제를 흡수시키세요.', '프랑스 임산부 스파 가이드'),
    (2, '시기별·부위별 마사지 테크닉', '허벅지 안쪽과 뒤쪽은 서혜부(사타구니) 방향으로 가볍게 밀어주며 마사지하세요.', '임산부 산전 림프 마사지 학회'),
    (2, '시기별·부위별 마사지 테크닉', '가슴 보습 시 유두 부위는 직접 자극하지 말고, 가슴 외곽선부터 쇄골 방향으로 쓸어 올려주세요.', '국제유방수유전문가협회'),
    (2, '시기별·부위별 마사지 테크닉', '등 뒤쪽과 허리 라인은 보호자(남편)에게 도움을 요청해 함께 마사지하세요.', '맘스홀릭 베이비'),
    (4, '시기별·부위별 마사지 테크닉', '붉은색 선이 보이기 시작하면 즉시 집중 케어를 시작하세요.', 'Journal of European Academy of Dermatology'),
    (3, '시기별·부위별 마사지 테크닉', '임신 20주 이후 체중 증가가 집중되는 허벅지 안쪽 및 엉덩이 하단 부위를 서혜부 림프절 방향으로 아래에서 위로 쓸어올려 부종과 피부 팽창 자극을 동시에 완화하세요.', 'NHS Pregnancy Care Guide'),
    (3, '시기별·부위별 마사지 테크닉', '복부 마사지 시 강하게 누르지 말고 손가락 지문 면을 활용해 꼬집듯이 림프를 자극하지 않는 부드러운 순환 마사지를 시행하세요.', '대한한방부인과학회'),
    (1, '안전한 성분 선택 및 주의사항', '단순 보습을 넘어 장벽 강화 임상시험 완료 여부를 확인하고 구매하세요. Barrier Lipid 4 등 특허 성분 유무를 체크하세요.', '피부과 전문의 닥터 칼럼'),
    (0, '안전한 성분 선택 및 주의사항', '임신 중 비타민 A 계열(레티놀·트레티노인) 성분은 반드시 피하세요.', 'American Academy of Dermatology'),
    (0, '안전한 성분 선택 및 주의사항', '파라벤, 옥시벤존, 인공 향료, 인공 색소가 전성분 상단에 위치한 바디 제품은 피하세요. 무첨가 약산성 저자극 제품을 선택하세요.', 'Environmental Working Group / 대한피부과학회'),
    (0, '안전한 성분 선택 및 주의사항', '자스민, 주니퍼, 마조람, 페퍼민트, 로즈마리 등 유산 위험이 있는 에센셜 오일은 피하고 전문가와 상의하세요. 에센셜 오일은 원액 그대로 바르지 말고 캐리어 오일에 희석해 사용하세요.', 'National Association for Holistic Aromatherapy'),
    (4, '안전한 성분 선택 및 주의사항', '임신 중 튼살 레이저 시술이나 화학적 케어는 피하세요. 염증, 발진 등 부작용이 생기거나 마취 성분이 태아에게 흡수될 수 있습니다.', '피부과 전문의 닥터 칼럼'),
    (1, '안전한 성분 선택 및 주의사항', '알레르기 병력이 있다면 신규 제품 사용 전 팔 안쪽에 24시간 패치 테스트를 먼저 진행하세요.', 'Contact Dermatitis Journal'),
    (3, '안전한 성분 선택 및 주의사항', '때타올이나 강한 스크럽제로 배를 문지르지 마세요. 표피 장벽이 파괴되어 튼살이 악화됩니다.', '대한피부과학회'),
    (0, '안전한 성분 선택 및 주의사항', '여드름 및 각질 케어 목적의 살리실산(BHA) 2% 초과 고농도 제품 및 미백 성분인 하이드로퀴논(Hydroquinone)은 태아 독성 위험이 있으므로 전성분 표에서 반드시 배제하세요.', 'U.S. FDA / Journal of the American Academy of Dermatology'),
    (0, '안전한 성분 선택 및 주의사항', '디에탄올아민(DEA), 트리에탄올아민(TEA) 등 계면활성제 부산물 노출 위험이 있는 합성 화합물 성분을 확인하고 피하세요.', 'Toxicological Sciences / EWG'),
    (5, '출산 후 튼살 케어', '출산 후 최소 3개월(초기 6주간은 하루 2회)까지 마사지 케어를 지속하세요. 급격히 배가 꺼지면서 진피층이 늘어져 튼살이 도드라질 수 있습니다.', 'Healthline'),
    (5, '출산 후 튼살 케어', '제왕절개 수술 부위 상처가 완전히 아문 후부터 상처 주변 튼살 케어를 시작하세요.', '대한산부인과학회'),
    (4, '출산 후 튼살 케어', '수유 시 가슴 튼살이나 유두 균열 케어에는 라놀린 등 유아 안전 검증 성분을 사용하세요.', 'La Leche League International'),
    (6, '출산 후 튼살 케어', '출산 후 6주 산음복구기 동안 복직근 이개(Abdominal Separation) 수치를 점검하고, 무리한 압박 마사지 대신 병풀 추출물(Centella Asiatica) 성분의 탄력 크림으로 진진피층 수축을 유도하세요.', 'Mayo Clinic / 대한재활의학회'),
    (7, '출산 후 튼살 케어', '수유 종료 후 이미 흰색으로 변한 튼살(Striae Albae)은 전문 피부과 상담을 통해 프락셀 레이저나 고주파(RF) 케어 등 맞춤 치료 방안을 검토하세요.', 'Dermatologic Surgery'),
    (1, '세안·목욕 및 실내 환경', '가습기를 활용해 실내 습도를 50~60%로 유지하세요. 피부 수분 증발을 차단할 수 있습니다.', '서울대학교병원 의학정보 / 대한피부과학회'),
    (1, '세안·목욕 및 실내 환경', '샤워 시 뜨거운 물 대신 미지근한 물을 사용하세요. 피부 유분이 빼앗기는 것을 방지할 수 있습니다.', '네이버 블로그 motherk1'),
    (1, '세안·목욕 및 실내 환경', '샤워 후 타월로 몸을 문지르지 말고 가볍게 눌러 물기만 흡수시키세요.', 'American Pregnancy Association'),
    (2, '세안·목욕 및 실내 환경', '피부 탄력 손실을 막기 위해 15분 이상의 장시간 탕욕이나 잦은 목욕은 피하세요.', 'British Journal of Dermatology'),
    (1, '세안·목욕 및 실내 환경', '에어컨이나 난방기 바람이 피부에 직접 닿지 않도록 가디건이나 덮개를 활용하세요.', '차병원 여성의학연구소'),
    (1, '세안·목욕 및 실내 환경', '샤워 후 사용하는 세안제 및 바디워시는 약산성(pH 5.5 안팎)의 무비누계(Soap-free) 세정제를 선택하여 피부 장벽 지질 유실을 줄이세요.', 'Journal of Clinical and Aesthetic Dermatology'),
    (1, '수면·자세 및 혈액 순환', '밤 10시~새벽 2시 사이에는 일찍 수면에 청하세요. 피부 재생 호르몬 분비가 가장 활발한 시간대입니다.', 'Sleep Medicine Reviews'),
    (1, '수면·자세 및 혈액 순환', '수면 시 바디필로우를 활용해 옆으로 누워 자는 자세를 취하세요. 복부 피부 압박을 줄이고 혈액순환을 도울 수 있습니다.', 'American Pregnancy Association'),
    (1, '수면·자세 및 혈액 순환', '의자에 앉을 때는 등받이에 쿠션을 받치고, 1시간마다 가벼운 스트레칭을 해주세요. 복부 접힘을 방지하고 하체 순환을 개선할 수 있습니다.', '국민건강보험공단'),
    (2, '수면·자세 및 혈액 순환', '휴식을 취할 때는 다리를 높게 올리고, 따뜻한 족욕을 병행하세요. 하체 부종을 줄이고 전신 혈류를 개선할 수 있습니다.', '대한산부인과학회 / 대한한방부인과학회'),
    (1, '수면·자세 및 혈액 순환', '100% 순면 소재의 넉넉한 속옷과 통풍이 잘되는 옷을 입으세요. 마찰 자극과 혈액순환 방해를 줄일 수 있습니다.', 'BabyCenter'),
    (1, '수면·자세 및 혈액 순환', '하루 10분 심호흡이나 명상으로 스트레스를 관리하세요. 스트레스 호르몬인 코르티솔에 의한 콜라겐 분해를 막을 수 있습니다.', 'Psychosomatic Medicine Journal'),
    (1, '수면·자세 및 혈액 순환', '하루 20~30분 가벼운 임산부 요가나 평지 걷기 운동을 실천하여 전신 미세혈관 순환을 촉진하고 피부 조직 세포로의 산소 공급을 확대하세요.', 'ACOG / 대한임산부운동학회'),
    (2, '수면·자세 및 혈액 순환', '오래 서 있거나 정적인 자세로 오래 앉아있는 경우 압박 스타킹(임산부 전용 의료용)을 착용하여 하체 미세혈관 울혈과 부종을 차단하세요.', 'Cochrane Database of Systematic Reviews'),
    (1, '식습관 및 체중 관리', '하루 8잔(약 1.5~2L)의 미지근한 물을 자주 마시세요. 이뇨 작용으로 체내 수분을 빼앗는 카페인 음료 대신 루이보스티나 물을 선택하세요.', 'Mayo Clinic / ACOG'),
    (1, '식습관 및 체중 관리', '비타민 C(귤·딸기·브로콜리), 오메가-3(등푸른 생선·견과류), 아연(계란·콩류·살코기)이 풍부한 식단을 챙기세요. 체내 콜라겐 합성을 돕고 세포 재생을 촉진합니다.', 'Mayo Clinic / WebMD / NIH'),
    (2, '식습관 및 체중 관리', '나트륨 섭취와 당분이 과도한 음료 및 디저트를 줄이세요. 부종으로 인한 피부 조직 팽창과 콜라겐 파괴(AGEs 생성)를 막을 수 있습니다.', '대한영양사협회 / Journal of Dermatological Science'),
    (1, '식습관 및 체중 관리', '갑작스러운 체중 증가를 막기 위해 균형 잡힌 식단과 가벼운 유산소 운동을 병행하세요.', 'U.S. Department of Health'),
    (6, '식습관 및 체중 관리', '출산 후 체중 감량 시 월 1~2kg 이내로 서서히 줄이세요. 급격한 감량은 피부 처짐을 유발합니다.', 'Journal of Women''s Health'),
    (2, '식습관 및 체중 관리', '주당 체중 증가량이 0.5kg을 초과하지 않도록 임신 전 BMI 기준 권장 체중 증가 가이드라인(총 11~16kg)을 준수하여 피부 급팽창 위험을 제어하세요.', 'Institute of Medicine / ACOG'),
    (1, '식습관 및 체중 관리', '콜라겐과 엘라스틴 합성을 활성화하는 프롤린 및 글리신 아미노산이 풍부한 단백질 식품(닭가슴살, 두부, 살코기)을 매끼 정량 섭취하세요.', 'American Journal of Clinical Nutrition'),
    (3, '야외활동 및 특이증상 대응', '외출 시 피부가 햇빛에 노출된다면 순한 무기자차 자외선 차단제를 발라 착색을 예방하세요.', 'American Academy of Dermatology'),
    (4, '야외활동 및 특이증상 대응', '피부가 가려울 때는 긁지 말고 차가운 수건으로 냉찜질을 하거나 보습제를 덧발라주세요.', 'Parents.com'),
    (8, '야외활동 및 특이증상 대응', '가려움과 함께 붉은 두드러기(수포)가 번지면 즉시 산부인과나 피부과 진료를 받으세요. 임신성 소양증(PUPPP)일 수 있습니다.', 'JAAD'),
    (8, '야외활동 및 특이증상 대응', '피부에 진물이 나거나 물집이 생기면 보습제 사용을 즉시 중단하고 전문의를 찾으세요.', '대한피부과학회'),
    (4, '야외활동 및 특이증상 대응', '야외 활동 후 자외선에 의해 열감이 생긴 복부 피부에는 칼라민 로션이나 멸균 알로에 베라 겔을 도포하여 피부 온도를 신속히 낮추세요.', 'Korean Journal of Dermatology'),
    (2, '보습 및 제품 레이어링', '실내 난방을 가동하는 겨울철에는 보습제 도포 후 100% 면 소재의 얇은 내의를 덧입어 피부 표면의 수분 손실을 이중으로 차단하세요.', 'National Eczema Association (nationaleczema.org)'),
    (2, '보습 및 제품 레이어링', '피부 장벽 기능을 높이는 나이아신아마이드(Niacinamide) 2~5% 함유 로션을 사용하여 진피층의 세라마이드 생성을 촉진시키고 탄력을 유지하세요.', 'Journal of Cosmetic Dermatology (onlinelibrary.wiley.com)'),
    (1, '보습 및 제품 레이어링', '입덧으로 인해 화장품 향에 민감해진 시기에는 무향(Unscented) 제품이 아닌 향료 무첨가(Fragrance-free) 원료 베이스 크림을 사용하여 후각 자극과 피부 자극을 동시에 줄이세요.', 'American College of Obstetricians and Gynecologists (acog.org)'),
    (3, '시기별·부위별 마사지 테크닉', '종아리 부종이 심할 때는 발목에서 무릎 방향으로 가볍게 쓸어올리듯 마사지하되, 혈관이 튀어나온 정맥류 부위는 직접 압박하지 말고 주변부만 가볍게 풀어주세요.', '대한정맥학회 (phlebology.or.kr)'),
    (2, '시기별·부위별 마사지 테크닉', '임신 28주 이후에는 태동이 활발해지므로, 손바닥 전체로 복부를 따뜻하게 감싸 안고 부드럽게 쓰다듬는 ''태담 마사지''를 하루 10분씩 병행하여 옥시토신 분비를 유도하세요.', '한국영유아발달학회 (kapcd.or.kr)'),
    (0, '안전한 성분 선택 및 주의사항', '화장품 전성분표에 ''향료(Fragrance/Parfum)''로 통합 표기된 성분 속에는 내분비계 교란 물질인 프탈레이트(Phthalates)가 숨어있을 수 있으므로 반드시 피하세요.', 'Environmental Working Group (ewg.org) / FDA (fda.gov)'),
    (0, '안전한 성분 선택 및 주의사항', '임산부에게 안전하다고 알려진 스위트 아몬드 오일이라도 평소 견과류 알레르기가 있다면 아나필락시스 위험이 있으므로 호호바 오일이나 식물성 스쿠알란으로 대체하세요.', 'American Academy of Allergy, Asthma & Immunology (aaaai.org)'),
    (0, '안전한 성분 선택 및 주의사항', '유해성 논란이 있는 페녹시에탄올(Phenoxyethanol) 보존제 대신 황금추출물, 모란뿌리추출물 등 식물 유래 추출물로 천연 방부 처리를 한 임산부 전용 비건 스킨케어를 고려하세요.', 'Safe Cosmetics Campaign (safecosmetics.org)'),
    (5, '출산 후 튼살 케어', '출산 후 복부 탄력 밴드(산후 복대)를 착용할 때는 피부와 직접 마찰되지 않도록 얇은 면 티셔츠 위에 착용하여 접촉성 피부염과 튼살 부위의 악화를 예방하세요.', '대한산부인과학회 (ksog.org)'),
    (1, '세안·목욕 및 실내 환경', '임신부의 체온이 일반인보다 높아 땀과 피지 분비가 많으므로, 침구류는 주 1회 60도 이상의 온수로 세탁하여 집먼지진드기로 인한 피부 자극과 소양증(가려움)을 예방하세요.', 'American Academy of Dermatology (aad.org)'),
    (0, '세안·목욕 및 실내 환경', '목욕 시 에센셜 오일이나 배스 밤을 푼 욕조를 사용할 경우, 바닥이 매우 미끄러울 수 있으므로 임산부 낙상 사고에 각별히 주의하며 미끄럼 방지 매트를 꼭 활용하세요.', 'American College of Nurse-Midwives (midwife.org)'),
    (3, '수면·자세 및 혈액 순환', '임신 후기 골반 통증(환도선다)이 허리와 엉덩이 튼살 부위의 뻐근함과 혼동될 수 있으므로, 임산부 전용 골반 지지 벨트를 착용하여 피부 쏠림과 근육 긴장을 동시에 줄여주세요.', '대한재활의학회 (karm.or.kr)'),
    (2, '수면·자세 및 혈액 순환', '수면 중 종아리 근육 경련(쥐)이 잦다면 혈액순환 저하의 신호이므로, 취침 전 수건을 발끝에 걸고 몸쪽으로 당기는 가벼운 하체 스트레칭을 실천하세요.', 'American Pregnancy Association (americanpregnancy.org)'),
    (2, '수면·자세 및 혈액 순환', '장거리 차량 이동 시 2시간마다 반드시 휴게소에 들러 10분 이상 걷기 운동을 실시하여 하체 정맥의 혈류 정체를 막고 부종으로 인한 피부 팽창을 예방하세요.', 'CDC Travelers'' Health (cdc.gov/travel)'),
    (2, '식습관 및 체중 관리', '최종당화산물(AGEs)이 진피층의 콜라겐을 굳게 만들어 피부가 쉽게 찢어지는 튼살을 유발하므로, 고기를 튀기거나 직화로 굽는 조리법 대신 찌거나 삶는 방식의 식단을 구성하세요.', 'Journal of the American Dietetic Association (jandonline.org)'),
    (2, '식습관 및 체중 관리', '변비로 인한 하복부 팽만감은 복부 피부를 물리적으로 더욱 팽창시키므로, 하루 25~30g의 식이섬유(차전자피, 자두, 해조류)를 8잔 이상의 물과 함께 반드시 섭취하세요.', 'World Gastroenterology Organisation (worldgastroenterology.org)'),
    (1, '식습관 및 체중 관리', '피부 재생 세포의 분열과 조직 형성을 돕기 위해 임신 중기부터는 엽산(Folic Acid)뿐만 아니라 철분과 단백질이 풍부한 시금치, 렌틸콩, 살코기 위주의 식단을 강화하세요.', 'WHO Guidelines on Maternal Nutrition (who.int)'),
    (4, '야외활동 및 특이증상 대응', '임신 중에는 멜라닌 자극 호르몬이 증가해 붉은 튼살이 자외선에 노출될 경우 짙은 갈색으로 영구 색소침착이 될 수 있으므로, 야외 수영 시 반드시 자외선이 차단되는 래시가드로 복부를 덮어주세요.', 'Journal of Clinical and Aesthetic Dermatology (jcadonline.com)'),
    (3, '야외활동 및 특이증상 대응', '여름철 야외 산책 시 모기 기피제를 피부에 직접 분사하지 말고 겉옷이나 신발에 뿌려, 튼살로 인해 얇아진 피부 장벽을 통해 유해 화학성분(DEET 등)이 체내 흡수되는 것을 차단하세요.', 'CDC (cdc.gov) / EPA (epa.gov)'),
    (3, '보습 및 제품 레이어링', '튼살 크림의 유효 성분 흡수율을 높이기 위해 주 1회 정도 입자가 고운 스크럽이나 저자극 PHA 성분으로 묵은 각질을 가볍게 제거한 후 보습을 진행하세요.', 'Journal of Dermatological Science (jdsjournal.com)'),
    (3, '시기별·부위별 마사지 테크닉', '임신 중기부터 유선이 발달하며 가슴 튼살이 생기기 쉬우므로, 바깥쪽에서 안쪽으로 원을 그리며 부드럽게 마사지하여 피부 탄력을 잃지 않도록 유지하세요.', 'American College of Obstetricians and Gynecologists (acog.org)'),
    (4, '시기별·부위별 마사지 테크닉', '허벅지와 엉덩이는 피하지방이 많아 급격히 팽창하므로, 손가락을 이용해 밀가루 반죽을 치대듯 가볍게 꼬집고 튕겨주는 핀칭(Pinching) 마사지를 병행하여 피부 유연성을 기르세요.', 'International Journal of Women''s Dermatology (ijwdonline.org)'),
    (2, '수면·자세 및 혈액 순환', '취침 시 왼쪽으로 누워 자는 자세(심스 체위)를 유지하여 하대정맥의 압박을 줄이고 혈액 순환을 원활하게 해 하체 부종과 피부 팽창을 방지하세요.', 'American Pregnancy Association (americanpregnancy.org)');
